const raw = $input.first()?.json || {};
const list = Array.isArray(raw.data) ? raw.data : (Array.isArray(raw) ? raw : [raw]);
return list.filter(i => i && (i.isStrategic === true || i.isStrategic === 'true')).map(item => ({ json: item }));

const customer = $('5. Fetch Customer Profile')?.first()?.json || $('4. Split Out Accounts')?.first()?.json || $json || {};
const customerId = customer.id;

// 1. Engagement from actual interactions
const interactionsRaw = $('6. Fetch Customer Interactions')?.first()?.json;
let engagement = null;
const interactionItems = Array.isArray(interactionsRaw) ? interactionsRaw : (interactionsRaw?.items || interactionsRaw?.data || null);
if (Array.isArray(interactionItems) && interactionItems.length > 0) {
  engagement = Math.min(100, Math.round(30 + interactionItems.length * 15));
} else if (typeof interactionsRaw?.score === 'number') {
  engagement = Math.min(100, Math.max(0, interactionsRaw.score));
}

// 2. Feedback from actual feedback history
const feedbackRaw = $('8. Fetch Feedback History')?.first()?.json;
let feedback = null;
const feedbackItems = Array.isArray(feedbackRaw) ? feedbackRaw : (feedbackRaw?.items || feedbackRaw?.data || null);
if (Array.isArray(feedbackItems) && feedbackItems.length > 0) {
  let total = 0, count = 0;
  for (const item of feedbackItems) {
    if (typeof item.score === 'number') { total += item.score; count++; }
    else if (typeof item.rating === 'number') { total += (item.rating / 5) * 100; count++; }
    else if (typeof item.nps === 'number') { total += item.nps * 10; count++; }
  }
  if (count > 0) feedback = Math.min(100, Math.max(0, Math.round(total / count)));
} else if (typeof feedbackRaw?.score === 'number') {
  feedback = Math.min(100, Math.max(0, feedbackRaw.score));
}

// 3. Open Issues (inversely scored: more open issues reduces health score)
const issuesRaw = $('9. Fetch Open Issues and Renewals')?.first()?.json;
let openIssues = null;
const issueItems = Array.isArray(issuesRaw) ? issuesRaw : (issuesRaw?.issues || issuesRaw?.items || null);
if (Array.isArray(issueItems)) {
  const openCount = issueItems.filter(i => !i.resolvedAt && (i.status === 'OPEN' || i.status === 'PENDING' || i.status === 'IN_PROGRESS' || !i.status)).length;
  openIssues = Math.max(0, 100 - openCount * 25);
} else if (typeof issuesRaw?.openIssuesCount === 'number') {
  openIssues = Math.max(0, 100 - issuesRaw.openIssuesCount * 25);
} else if (typeof issuesRaw?.score === 'number') {
  openIssues = Math.min(100, Math.max(0, issuesRaw.score));
}

// 4. Follow-up completion from actual enrollments
const followUpRaw = $('7. Fetch Follow-up History')?.first()?.json;
let followUpCompletion = null;
const enrollments = Array.isArray(followUpRaw) ? followUpRaw : (followUpRaw?.items || followUpRaw?.data || null);
if (Array.isArray(enrollments) && enrollments.length > 0) {
  const completed = enrollments.filter(e => e.status === 'COMPLETED').length;
  const active = enrollments.filter(e => e.status === 'ACTIVE').length;
  followUpCompletion = Math.min(100, Math.round(((completed + active * 0.5) / enrollments.length) * 100));
} else if (typeof followUpRaw?.completionRate === 'number') {
  followUpCompletion = Math.min(100, Math.max(0, Math.round(followUpRaw.completionRate)));
} else if (typeof followUpRaw?.score === 'number') {
  followUpCompletion = Math.min(100, Math.max(0, followUpRaw.score));
}

const evidence = [];
if (engagement !== null) evidence.push(`Interactions: ${interactionItems?.length || 1} records`);
if (feedback !== null) evidence.push(`Feedback: ${feedbackItems?.length || 1} reviews`);
if (openIssues !== null) evidence.push(`Issue metric: ${openIssues}/100`);
if (followUpCompletion !== null) evidence.push(`Follow-up completion: ${followUpCompletion}%`);

return [{
  json: {
    customerId,
    engagement,
    feedback,
    openIssues,
    followUpCompletion,
    evidence
  }
}];

const d = $json;
const missing = [];
if (d.engagement === null || d.engagement === undefined) missing.push('engagement');
if (d.feedback === null || d.feedback === undefined) missing.push('feedback');
if (d.openIssues === null || d.openIssues === undefined) missing.push('openIssues');
if (d.followUpCompletion === null || d.followUpCompletion === undefined) missing.push('followUpCompletion');
return [{
  json: {
    ...d,
    missingData: missing,
    hasSufficientData: missing.length === 0
  }
}];

const snapshot = $('12. Call Backend Account Health API').item.json;
const customerId = $('10. Normalize Account Data').item.json.customerId;
return [{
  json: {
    saved: Boolean(snapshot.id),
    customerId,
    snapshotId: snapshot.id,
    score: snapshot.score,
    status: snapshot.status,
    hasRiskOrOpportunity: ['AT_RISK', 'CRITICAL'].includes(snapshot.status)
  }
}];

const customerId = $('10. Normalize Account Data').item.json.customerId;
const profile = $('5. Fetch Customer Profile')?.first()?.json || {};
const snapshot = $('12. Call Backend Account Health API').item.json;
return [{
  json: {
    customerId,
    ownerId: profile.createdBy,
    customerName: profile.name || 'Strategic Account',
    healthStatus: snapshot.status,
    healthScore: snapshot.score,
    taskType: 'RETENTION',
    priority: snapshot.status === 'CRITICAL' ? 'URGENT' : 'HIGH',
    idempotencyKey: customerId + ':account-health:alert:' + new Date().toISOString().slice(0, 10)
  }
}];

const customerId = $('10. Normalize Account Data')?.first()?.json?.customerId || $json?.customerId;
console.log(`Account health evaluation skipped or insufficient data for customer ${customerId}`);
return [{ json: { handled: true, customerId, status: 'INSUFFICIENT_DATA' } }];

const customerId = $('10. Normalize Account Data')?.first()?.json?.customerId || $json?.customerId;
console.log(`WF15 execution completed for customer ${customerId}`);
return [{ json: { logged: true, customerId, completedAt: new Date().toISOString() } }];
